import{_ as a,o as t,c as o,a3 as r}from"./chunks/framework.BlfGB29P.js";const g=JSON.parse('{"title":"Always patch ha-card (Experimental)","description":"Learn how to enable the patching of ha-card at all times with this experimental setting","frontmatter":{"title":"Always patch ha-card (Experimental)","description":"Learn how to enable the patching of ha-card at all times with this experimental setting"},"headers":[],"relativePath":"en/projects/uix/extras/always-patch-ha-card.md","filePath":"en/projects/uix/extras/always-patch-ha-card.md","lastUpdated":1794129659000}'),i={name:"en/projects/uix/extras/always-patch-ha-card.md"};function n(s,e,c,h,l,d){return t(),o("div",null,[...e[0]||(e[0]=[r('<blockquote><p>Adapted from the canonical English UIX documentation by <a href="https://github.com/Lint-Free-Technology/uix" target="_blank" rel="noreferrer">Lint-Free-Technology/uix</a>, <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noreferrer">CC BY 4.0</a>. Source: <code>master</code> / <strong>9.0.0</strong>, revision <a href="https://github.com/Lint-Free-Technology/uix/commit/f63ebbdda5294fe0b9d31d89d4942496ebe55722" target="_blank" rel="noreferrer">f63ebbd</a>, reviewed 5 November 2026. Requires Home Assistant 2026.11.0 or later. Markup adapted for this site; the <a href="https://uix.lf.technology/" target="_blank" rel="noreferrer">original documentation</a> remains authoritative.</p></blockquote><h1 id="always-patch-ha-card" tabindex="-1">Always patch ha-card <a class="header-anchor" href="#always-patch-ha-card" aria-label="Permalink to &quot;Always patch ha-card&quot;">​</a></h1><p>By default, UIX does not patch <code>ha-card</code> if it cannot find a card config in the first Frontend or custom element in its ancestor DOM tree. This experimental option allows for always patching ha-card element so theme variable <code>uix-card(-yaml)</code> can apply. <code>ha-card</code> without config may be used on config or custom panels.</p><p>When <code>ha-card</code> is patched without config the class <code>type-generic-card</code> will be added to <code>ha-card</code>.</p><h2 id="setting-via-the-integration-ui" tabindex="-1">Setting via the integration UI <a class="header-anchor" href="#setting-via-the-integration-ui" aria-label="Permalink to &quot;Setting via the integration UI&quot;">​</a></h2><p>The option is <strong>unset by default</strong>. To set the option:</p><ol><li>In Home Assistant, go to <strong>Settings → Devices &amp; Services → UI eXtension → Configure</strong>.</li><li>Select <strong>Experimental settings</strong> from the menu.</li><li>Toggle <strong>Always patch ha-card</strong> on.</li><li>Save.</li></ol><p>The setting is available immediately across all connected browser sessions. A page reload may be required for the setting to take effect.</p><h2 id="behavior-when-set" tabindex="-1">Behavior when set <a class="header-anchor" href="#behavior-when-set" aria-label="Permalink to &quot;Behavior when set&quot;">​</a></h2><p>When this option is set:</p><ul><li><code>ha-card</code> is always patched even when there is no card config available.</li><li>When patched in this way the class <code>type-generic-card</code> will be added to <code>ha-card</code>.</li></ul>',11)])])}const m=a(i,[["render",n]]);export{g as __pageData,m as default};
